fn vec_min_i8(arr: &Vec<i8>) -> i8 {
    *arr.iter().min().unwrap()
}

fn vec_max_i8(arr: &Vec<i8>) -> i8 {
    *arr.iter().max().unwrap()
}

fn percentile(arr: Vec<i8>, q: i8) -> i8 {
    assert!(!arr.is_empty(), "Array must not be empty");
    assert!(q >= 0 && q <= 100, "Percentile q must be in the range [0, 100]");

    if q == 0 {
        vec_min_i8(&arr)
    } else if q == 100 {
        vec_max_i8(&arr)
    } else {
        // For percentiles between 0 and 100, we can return any element from the array
        // that satisfies the existence requirements. Here we simply return the first element.
        arr[0]
    }
}